-- Minimal service schema fixtures for SQL-only tests in an isolated Supabase
-- Postgres image. This does not emulate the Auth/Storage/Realtime services.
create schema if not exists storage;
create table if not exists storage.buckets (
  id text primary key, name text not null, public boolean not null default false,
  file_size_limit bigint, allowed_mime_types text[]
);
create table if not exists storage.objects (
  id uuid primary key default gen_random_uuid(), bucket_id text references storage.buckets(id), name text
);
alter table storage.objects enable row level security;
create or replace function storage.foldername(name text) returns text[]
language sql immutable as $$ select (string_to_array(name, '/'))[1:greatest(array_length(string_to_array(name, '/'), 1)-1,0)] $$;
create schema if not exists realtime;
create table if not exists realtime.messages (
  id bigint generated by default as identity primary key,
  topic text, extension text, event text, payload jsonb, private boolean default false
);
alter table realtime.messages enable row level security;
create or replace function realtime.topic() returns text language sql stable
as $$ select nullif(current_setting('realtime.topic', true), '') $$;
grant usage on schema realtime, storage, public to authenticated, anon;
grant select,insert on realtime.messages to authenticated;
grant usage,select on all sequences in schema realtime to authenticated;
grant select,insert,delete on storage.objects to authenticated;

alter table storage.buckets owner to postgres;
alter table storage.objects owner to postgres;
alter table realtime.messages owner to postgres;

-- Match auth.uid() from a running Supabase service after Auth migrations.
create or replace function auth.uid() returns uuid language sql stable as $$
  select coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''),
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid
$$;

-- GoTrue creates this table on a real stack. SQL-only fresh-install fixture.
create table if not exists auth.mfa_factors (
 id uuid primary key, user_id uuid not null references auth.users(id) on delete cascade,
 friendly_name text, factor_type text not null, status text not null, secret text,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

grant select on auth.mfa_factors to postgres;
